import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String recipe = sc.nextLine();
        int[] n = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int[] p = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        long budget = Long.parseLong(sc.nextLine());

        int[] k = new int[3];
        k[0] = countChar(recipe, 'B');
        k[1] = countChar(recipe, 'S');
        k[2] = countChar(recipe, 'C');

        long l = 0;
        long r = budget + Math.max(n[0], Math.max(n[1], n[2]));
        long x = 0;

        while (l <= r) {
            long m = (l + r) / 2;
            long sumCost = 0;

            for (int i = 0; i < 3; i++) {
                if (k[i] == 0) continue;
                long need = (long) k[i] * m - n[i];
                long toBuy = nonNeg(need);
                sumCost += toBuy * p[i];
                if (sumCost > budget) break;
            }

            if (sumCost < budget) {
                l = m + 1;
                x = m;
            } else if (sumCost > budget) {
                r = m - 1;
            } else {
                x = m;
                break;
            }
        }

        System.out.println(x);
    }

    private static long nonNeg(long x) {
        return x < 0 ? 0 : x;
    }

    private static int countChar(String s, char c) {
        int cnt = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == c) cnt++;
        }
        return cnt;
    }
}

